func alertmanagerSnippet(url, token string) string {
	return "receivers:\n" +
		"  - name: teamster\n" +
		"    webhook_configs:\n" +
		"      - url: " + url + "\n" +
		"        http_config:\n" +
		"          authorization:\n" +
		"            type: Bearer\n" +
		"            credentials: " + token + "\n"
}

